    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوسين الداخليين","math":"<span dir=\"ltr\" class=\"expr\">(8 - x)</span> و <span dir=\"ltr\" class=\"expr\">(x - 8)</span> متقابلان"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [9 - 8 + x] = -9 + 8 - x</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [-7 - x + 8] = 7 + x - 8</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = x - 9 + 8 - x + 7 + x - 8</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (x - x + x) + (-9 + 8 + 7 - 8)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-9 + 8 + 7 - 8 = -2</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">x = 6</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = 6 - 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 4</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(x) - 2 = -3</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">x = (-3) - (-2)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -1</span>"}],
