    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span> حيث <span dir=\"ltr\" class=\"expr\">N = -5 + (-b + 5) - (-a + 3) - (-5 + c - 4)</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 2</span> و <span dir=\"ltr\" class=\"expr\">b = -5</span> و <span dir=\"ltr\" class=\"expr\">c = -2</span> <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 2</span> و <span dir=\"ltr\" class=\"expr\">b = -5</span> و <span dir=\"ltr\" class=\"expr\">c = -2</span> جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">11 + |x| = -6</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 5) = -b + 5</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 3) = a - 3</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-5 + c - 4) = 5 - c + 4</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -5 - b + 5 + a - 3 + 5 - c + 4</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-5 + 5 - 3 + 5 + 4)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-5 + 5 - 3 + 5 + 4 = 6</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = 2 - (-5) - (-2) + 6</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">2 - (-5) - (-2) + 6 = 15</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 15</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-6) - 11</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-6) - 11 = -17</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-17 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
