    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 1</span> حيث <span dir=\"ltr\" class=\"expr\">N = -6 + (-b + 5) - (-a + 5) - (-3 + c - 4)</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 1</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = -2</span> و <span dir=\"ltr\" class=\"expr\">b = 3</span> و <span dir=\"ltr\" class=\"expr\">c = 1</span> <span dir=\"ltr\" class=\"expr\">N = a - b - c + 1</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 1</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = -2</span> و <span dir=\"ltr\" class=\"expr\">b = 3</span> و <span dir=\"ltr\" class=\"expr\">c = 1</span> جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">10 + |x| = 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 5) = -b + 5</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 5) = a - 5</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-3 + c - 4) = 3 - c + 4</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -6 - b + 5 + a - 5 + 3 - c + 4</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-6 + 5 - 5 + 3 + 4)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 + 5 - 5 + 3 + 4 = 1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 1</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 1</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = (-2) - 3 - 1 + 1</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">(-2) - 3 - 1 + 1 = -5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = -5</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 4 - 10</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 - 10 = -6</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-6 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
