    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span> حيث <span dir=\"ltr\" class=\"expr\">N = -2 + (-b + 6) - (-a + 2) - (-3 + c - 4)</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 5</span> و <span dir=\"ltr\" class=\"expr\">b = 9</span> و <span dir=\"ltr\" class=\"expr\">c = 6</span> <span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 5</span> و <span dir=\"ltr\" class=\"expr\">b = 9</span> و <span dir=\"ltr\" class=\"expr\">c = 6</span> جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">12 - (4 - |x|) = 6</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 6) = -b + 6</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 2) = a - 2</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-3 + c - 4) = 3 - c + 4</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -2 - b + 6 + a - 2 + 3 - c + 4</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-2 + 6 - 2 + 3 + 4)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 6 - 2 + 3 + 4 = 9</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = 5 - 9 - 6 + 9</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">5 - 9 - 6 + 9 = -1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = -1</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">12 - 4 + |x| = 6</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">12 - 4 = 8</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">8 + |x| = 6</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 6 - 8</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">6 - 8 = -2</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-2 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
