    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-4 + x = -7</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-4 - (6 - x) = -5</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">1 + (|x| - (-9)) = -9</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">|x| - (-2) = 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-7) - (-4)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-7) - (-4) = -3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -3</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-4 + (-3) = -7</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-4 - 6 + x = -5</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 - 6 = -10</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-10 + x = -5</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-5) - (-10)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-5) - (-10) = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 5</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-4 - (6 - 5) = -5</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">1 + |x| - (-9) = -9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">1 - (-9) = 10</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">10 + |x| = -9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-9) - 10</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-9) - 10 = -19</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-19 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">|x| = 4 + (-2)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 + (-2) = 2</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">2 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 2</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -2</span>"}],
