    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-10 + x = 0</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">x - (-6) = -3</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-6 - (|x| + 9) = -1</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-6 + (|x| - 2) = 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 0 - (-10)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">0 - (-10) = 10</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 10</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-10 + 10 = 0</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">x = (-3) + (-6)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-3) + (-6) = -9</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -9</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">(-9) - (-6) = -3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-6 - |x| - 9 = -1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 - 9 = -15</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-15 - |x| = -1</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-15) - (-1)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-15) - (-1) = -14</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-14 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">-6 + |x| - 2 = 4</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 - 2 = -8</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-8 + |x| = 4</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 4 - (-8)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 - (-8) = 12</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">12 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 12</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -12</span>"}],
