    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-10 + [-7 - x] = 3</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">9 - x = 3</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">2 + (|x| - (-2)) = -3</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-10 + |x| = 5</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">-10 + -7 - x = 3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-10 + (-7) = -17</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-17 - x = 3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-17) - 3</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-17) - 3 = -20</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -20</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-10 + [-7 - (-20)] = 3</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 9 - 3</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">9 - 3 = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 6</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">9 - 6 = 3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">2 + |x| - (-2) = -3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 - (-2) = 4</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4 + |x| = -3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-3) - 4</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-3) - 4 = -7</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-7 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 5 - (-10)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">5 - (-10) = 15</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">15 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 15</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -15</span>"}],
