    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">x - 9 = 9</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-4 + x = -3</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-4 - |x| = 5</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-8 + (|x| - 2) = 6</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">x = 9 + 9</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">9 + 9 = 18</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 18</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">18 - 9 = 9</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-3) - (-4)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-3) - (-4) = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 1</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-4 + 1 = -3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-4) - 5</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-4) - 5 = -9</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-9 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">-8 + |x| - 2 = 6</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-8 - 2 = -10</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-10 + |x| = 6</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 6 - (-10)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">6 - (-10) = 16</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">16 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 16</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -16</span>"}],
