    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 14</span> حيث <span dir=\"ltr\" class=\"expr\">G = -[-6 - (8 - a)] - [(b - 8) + (8 - a)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 14</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">G = 12</span> و <span dir=\"ltr\" class=\"expr\">G = -b + 14</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 14</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">G = 12</span> و احسب <span dir=\"ltr\" class=\"expr\">b + |-G| + 8</span> إذا كان <span dir=\"ltr\" class=\"expr\">b = -5</span> <span dir=\"ltr\" class=\"expr\">G = -b + 14</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نلاحظ المجموعة المتكرّرة","math":"<span dir=\"ltr\" class=\"expr\">(8 - a)</span> موجودة مرّتين بإشارتين متعاكستين"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">-[-6 - (8 - a)] = 6 + 8 - a</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(b - 8) + (8 - a)] = -b + 8 - 8 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">G = 6 + 8 - a - b + 8 - 8 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">G = (-a + a) + (8 - 8) - b + (6 + 8)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">6 + 8 + 8 - 8 = 14</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 14</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 14</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) + 14 = 12</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = 12 - 14</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -2</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب G","math":"<span dir=\"ltr\" class=\"expr\">G = -(-5) + 14 = 19</span>"},{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = |G|</span> لأنّ العددين المتقابلين لهما نفس القيمة المطلقة"},{"quoi":"نحسب القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = 19</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b + |-G| + 8 = (-5) + 19 + 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(-5) + 19 + 8 = 22</span>"}],
