    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نلاحظ المجموعة المتكرّرة","math":"<span dir=\"ltr\" class=\"expr\">(8 - a)</span> موجودة مرّتين بإشارتين متعاكستين"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">-[-9 - (8 - a)] = 9 + 8 - a</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(b - 12) + (8 - a)] = -b + 12 - 8 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">G = 9 + 8 - a - b + 12 - 8 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">G = (-a + a) + (8 - 8) - b + (9 + 12)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">9 + 8 + 12 - 8 = 21</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 21</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 21</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) + 21 = -15</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = (-15) - 21</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -36</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب G","math":"<span dir=\"ltr\" class=\"expr\">G = -(-2) + 21 = 23</span>"},{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = |G|</span> لأنّ العددين المتقابلين لهما نفس القيمة المطلقة"},{"quoi":"نحسب القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = 23</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b + |-G| + 6 = (-2) + 23 + 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(-2) + 23 + 6 = 27</span>"}],
