    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">4 - (-5) + x = 8</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">4 - (-5) = 9</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">9 + x = 8</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 8 - 9</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">8 - 9 = -1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -1</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">4 - (-5 - (-1)) = 8</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">-2 + -5 - |x| = -6</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + (-5) = -7</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-7 - |x| = -6</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-7) - (-6)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-7) - (-6) = -1</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-1 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">-9 + |x| - (-1) = -7</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-9 - (-1) = -8</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-8 + |x| = -7</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-7) - (-8)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-7) - (-8) = 1</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">1 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 1</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -1</span>"}],
